"use client"

import { useEffect, useRef, useState } from "react"

export function useInViewOnce(threshold = 0.35) {
  const ref = useRef<HTMLDivElement>(null)
  const [active, setActive] = useState(false)

  useEffect(() => {
    const el = ref.current
    if (!el || active) return

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry?.isIntersecting) {
          setActive(true)
          observer.disconnect()
        }
      },
      { threshold }
    )

    observer.observe(el)
    return () => observer.disconnect()
  }, [active, threshold])

  return { ref, active }
}

@keyframes fsv3-highlight-block {
  from {
    background-size: 100% 0%;
  }
  to {
    background-size: 100% 100%;
  }
}

@keyframes fsv3-index-settle {
  0% {
    opacity: 0.76;
    transform: translateY(0.02em) scale(0.96);
  }
  65% {
    opacity: 1;
    transform: translateY(-0.015em) scale(1.04);
  }
  100% {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.fsv3-highlight {
  position: relative;
  line-height: 1;
  background-image: linear-gradient(
    color-mix(in oklch, currentColor 14%, transparent),
    color-mix(in oklch, currentColor 14%, transparent)
  );
  background-position: left bottom;
  background-repeat: no-repeat;
  background-size: 100% 0%;
  animation: fsv3-highlight-block 760ms cubic-bezier(0.2, 0.8, 0.2, 1) 1 both;
}

.fsv3-highlight__index {
  display: inline-block;
  animation: fsv3-index-settle 520ms ease-out 1 both;
  animation-delay: inherit;
  transform-origin: center;
}

@media (prefers-reduced-motion: reduce) {
  .fsv3-highlight,
  .fsv3-highlight__index {
    animation: none;
    transform: none;
    background-size: 100% 100%;
  }
}

@keyframes fsv3-illus-draw {
  to {
    stroke-dashoffset: 0;
  }
}

@keyframes fsv3-illus-fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes fsv3-illus-scale-in {
  from {
    opacity: 0;
    transform: scale(0.88);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes fsv3-illus-slide-in {
  from {
    opacity: 0;
    transform: translateX(6px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes fsv3-illus-endpoint-in {
  0% {
    opacity: 0;
    transform: scale(0.4);
  }
  70% {
    transform: scale(1.12);
  }
  100% {
    opacity: 1;
    transform: scale(1);
  }
}

.fsv3-fn-wedge {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
}

.fsv3-fn-gap {
  opacity: 0;
}

.fsv3-fn-gap rect {
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
}

.fsv3-fn-chart--active .fsv3-fn-wedge--1 {
  animation: fsv3-illus-scale-in 520ms cubic-bezier(0.22, 1, 0.36, 1) 120ms forwards;
}

.fsv3-fn-chart--active .fsv3-fn-wedge--2 {
  animation: fsv3-illus-scale-in 520ms cubic-bezier(0.22, 1, 0.36, 1) 260ms forwards;
}

.fsv3-fn-chart--active .fsv3-fn-wedge--3 {
  animation: fsv3-illus-scale-in 560ms cubic-bezier(0.16, 1, 0.3, 1) 400ms forwards;
}

.fsv3-fn-chart--active .fsv3-fn-wedge--4 {
  animation: fsv3-illus-scale-in 480ms ease-out 540ms forwards;
}

.fsv3-fn-chart--active .fsv3-fn-gap {
  animation: fsv3-illus-fade-in 360ms ease-out 680ms forwards;
}

.fsv3-fn-chart--active .fsv3-fn-gap rect {
  animation: fsv3-illus-draw 640ms cubic-bezier(0.22, 1, 0.36, 1) 720ms forwards;
}

.fsv3-do-path {
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
}

.fsv3-do-node {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
}

.fsv3-do-callout {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
}

.fsv3-do-chart--active .fsv3-do-path {
  animation: fsv3-illus-draw 900ms cubic-bezier(0.22, 1, 0.36, 1) 140ms forwards;
}

.fsv3-do-chart--active .fsv3-do-node--1 {
  animation: fsv3-illus-scale-in 360ms ease-out 480ms forwards;
}

.fsv3-do-chart--active .fsv3-do-node--2 {
  animation: fsv3-illus-scale-in 400ms cubic-bezier(0.22, 1, 0.36, 1) 620ms forwards;
}

.fsv3-do-chart--active .fsv3-do-node--3 {
  animation: fsv3-illus-scale-in 360ms ease-out 760ms forwards;
}

.fsv3-do-chart--active .fsv3-do-node--4 {
  animation: fsv3-illus-scale-in 320ms ease-out 880ms forwards;
}

.fsv3-do-chart--active .fsv3-do-callout {
  animation: fsv3-illus-slide-in 560ms cubic-bezier(0.22, 1, 0.36, 1) 980ms forwards;
}

@keyframes fsv3-ex-draw {
  to {
    stroke-dashoffset: 0;
  }
}

@keyframes fsv3-ex-fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes fsv3-ex-area-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 0.12;
  }
}

@keyframes fsv3-ex-endpoint-in {
  0% {
    opacity: 0;
    transform: scale(0.4);
  }
  70% {
    transform: scale(1.12);
  }
  100% {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes fsv3-ex-node-in {
  from {
    opacity: 0;
    transform: scale(0.85);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

.fsv3-ex-control {
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
}

.fsv3-ex-lift__line {
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
}

.fsv3-ex-lift__area {
  opacity: 0;
}

.fsv3-ex-launch {
  opacity: 0;
}

.fsv3-ex-lift__endpoint {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
}

.fsv3-ex-pipeline__node,
.fsv3-ex-pipeline__link {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: center;
}

.fsv3-ex-chart--active .fsv3-ex-control {
  animation: fsv3-ex-draw 680ms cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

.fsv3-ex-chart--active .fsv3-ex-control--variant {
  animation-delay: 180ms;
}

.fsv3-ex-chart--active .fsv3-ex-launch {
  animation: fsv3-ex-fade-in 420ms ease-out 520ms forwards;
}

.fsv3-ex-chart--active .fsv3-ex-lift__line {
  animation: fsv3-ex-draw 1.15s cubic-bezier(0.16, 1, 0.3, 1) 680ms forwards;
}

.fsv3-ex-chart--active .fsv3-ex-lift__area {
  animation: fsv3-ex-area-in 720ms cubic-bezier(0.22, 1, 0.36, 1) 1.35s forwards;
}

.fsv3-ex-chart--active .fsv3-ex-lift__endpoint {
  animation: fsv3-ex-endpoint-in 520ms cubic-bezier(0.34, 1.4, 0.64, 1) 1.65s forwards;
}

.fsv3-ex-chart--active .fsv3-ex-pipeline__node:nth-child(1),
.fsv3-ex-chart--active .fsv3-ex-pipeline__link:nth-child(2) {
  animation: fsv3-ex-node-in 400ms ease-out 1.85s forwards;
}

.fsv3-ex-chart--active .fsv3-ex-pipeline__node:nth-child(3),
.fsv3-ex-chart--active .fsv3-ex-pipeline__link:nth-child(4) {
  animation: fsv3-ex-node-in 400ms ease-out 2s forwards;
}

.fsv3-ex-chart--active .fsv3-ex-pipeline__node--impact {
  animation: fsv3-ex-node-in 480ms cubic-bezier(0.22, 1, 0.36, 1) 2.15s forwards;
}

@media (prefers-reduced-motion: reduce) {
  .fsv3-fn-wedge,
  .fsv3-fn-gap,
  .fsv3-do-path,
  .fsv3-do-node,
  .fsv3-do-callout {
    opacity: 1;
    transform: none;
    animation: none;
  }

  .fsv3-fn-gap rect,
  .fsv3-do-path {
    stroke-dashoffset: 0;
  }

  .fsv3-ex-control,
  .fsv3-ex-lift__line {
    stroke-dashoffset: 0;
    animation: none;
  }

  .fsv3-ex-lift__area {
    opacity: 0.12;
    animation: none;
  }

  .fsv3-ex-launch,
  .fsv3-ex-lift__endpoint,
  .fsv3-ex-pipeline__node,
  .fsv3-ex-pipeline__link {
    opacity: 1;
    transform: none;
    animation: none;
  }
}
